from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x,g[y][x]))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx] and not seen[ny][nx]:
                                seen[ny][nx]=True; q.append((ny,nx))
                ys=[a for a,b,c_ in c]; xs=[b for a,b,c_ in c]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                out.append({'bbox':(y0,y1,x0,x1),'size':len(c),
                    'mask':[[1 if g[y][x] else 0 for x in range(x0,x1+1)] for y in range(y0,y1+1)],
                    'colors':sorted({c_ for _,_,c_ in c})})
    return out
