def mask(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx] and not seen[ny][nx]:
                                seen[ny][nx]=True; q.append((ny,nx))
                ys=[a for a,b in cells]; xs=[b for a,b in cells]
                out.append((min(ys),min(xs),max(ys),max(xs),{(y-min(ys),x-min(xs)) for y,x in cells}))
    return out
def transform(g):
    ms=mask(g); a,b=ms[0],ms[1]
    H=max(a[2]-a[0],b[2]-b[0])+1; W=max(a[3]-a[1],b[3]-b[1])+1
    out=[[0]*W for _ in range(H)]
    for y in range(H):
        for x in range(W):
            if ((y,x) in a[4]) != ((y,x) in b[4]): out[y][x]=8
    # crop
    ys=[y for y in range(H) for x in range(W) if out[y][x]]; xs=[x for y in range(H) for x in range(W) if out[y][x]]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    return [row[x0:x1+1] for row in out[y0:y1+1]]
